import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';

export default function VolunteerDonorSection({ me, events, token, setMsg, activities }) {

  // 🔥 FIX 1 — prevent crash before `me` loads
  if (!me) {
    return <div>Loading...</div>;
  }

  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);
  const [view, setView] = useState("donate");
  const [showFeedback, setShowFeedback] = useState(false);

  useEffect(() => {
    const fetchAchievements = async () => {
      try {
        const res = await fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/user/achievements", {
          headers: { Authorization: `Bearer ${token}` }
        });
        const data = await res.json();
        setAchievements(data);
      } catch (err) {}
    };
    fetchAchievements();
  }, [token]);

  useEffect(() => {
    const fetchMyNgos = async () => {
      try {
        const res = await fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/user/myngos", {
          headers: { Authorization: `Bearer ${token}` }
        });
        const data = await res.json();
        setMyNgos(data || []);
      } catch (err) {}
    };
    fetchMyNgos();
  }, [token]);

  return (
    <div className="volunteer-donor-container">

      {/* Profile Details */}
      <div className="profile-card">
        <h3>Your Profile</h3>
        <p><strong>Name:</strong> {me?.name}</p> {/* FIX 2 */}
        <p><strong>Email:</strong> {me?.email}</p>
        <p><strong>Points:</strong> {me?.points}</p> {/* FIX 2 */}

        {achievements && (
          <div className="achievements">
            <h4>Achievements</h4>
            <ul>
              {achievements.map((a, i) => (
                <li key={i}>{a}</li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {/* View Switch */}
      <div className="view-switch">
        <button onClick={() => setView("donate")} className={view === "donate" ? "active" : ""}>Donate</button>
        <button onClick={() => setView("volunteer")} className={view === "volunteer" ? "active" : ""}>Volunteer</button>
        <button onClick={() => setView("activities")} className={view === "activities" ? "active" : ""}>My Activities</button>
      </div>

      {/* Render Sections */}
      <div className="section-content">
        {view === "donate" && (
          <Donate
            token={token}
            setMsg={setMsg}
            myNgos={myNgos}
            selectedNgo={selectedNgo}
            setSelectedNgo={setSelectedNgo}
          />
        )}

        {view === "volunteer" && (
          <Volunteer
            events={events}
            token={token}
            setMsg={setMsg}
            myNgos={myNgos}
            setShowFeedback={setShowFeedback}
          />
        )}

        {view === "activities" && (
          <div className="activities-list">
            <h3>Your Recent Activities</h3>
            {activities?.length === 0 ? (
              <p>No activities recorded.</p>
            ) : (
              activities?.map((act, idx) => (
                <div key={idx} className="activity-card">
                  <p><strong>Type:</strong> {act.type}</p>
                  <p><strong>Date:</strong> {new Date(act.date).toLocaleString()}</p>
                  <p><strong>Details:</strong> {act.details}</p>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* Feedback Popup */}
      {showFeedback && (
        <Feedback token={token} setShowFeedback={setShowFeedback} setMsg={setMsg} />
      )}
    </div>
  );
}
